def to_base_r(n, r):
    """Convert n to base r representation, return list of digits (most significant first)."""
    if n == 0:
        return [0]
    digits = []
    while n > 0:
        digits.append(n % r)
        n //= r
    return digits[::-1]

def check_base(r):
    """Check if base r satisfies the conditions."""
    x = 9 * (r**3 + r**2 + r + 1)
    x_sq = x ** 2

    digits = to_base_r(x_sq, r)
    n_digits = len(digits)

    if n_digits != 8:
        return False, None, None, None, None

    is_palindrome = all(digits[i] == digits[7-i] for i in range(8))
    sum_23 = digits[1] + digits[2] if len(digits) >= 3 else None

    return is_palindrome, digits, n_digits, sum_23, x_sq

solutions = []
