{"operation":"run_python","code":"import itertools

def count_ways(n):
    grid_size = n * n
    if n == 1:
        return 1

    # Adjacency matrix for the grid (including diagonals)
    adj = {}
    for r in range(n):
        for c in range(n):
            neighbors = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0: continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        neighbors.append(nr * n + nc)
            adj[r * n + c] = neighbors

    count = 0
    for p in itertools.permutations(range(1, grid_size + 1)):
        valid = True
        for u in range(grid_size):
            for v in adj[u]:
                if abs(p[u] - p[v]) > n + 1:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            count += 1
    return count

print("n=2:", count_ways(2))
