{"operation":"run_python","code":"def count_tasty(n):
    total = 0
    from itertools import combinations
    # A tuple is non-decreasing: 1 <= a_1 <= ... <= a_k
    # It is valid if there exists a subset S of size k such that sorted(a) <= sorted(S) element-wise.
    # This is equivalent to: for all j, the number of a_i > j is <= n - j.
    # Let's just generate all non-decreasing sequences and check validity.

    def is_valid(a, n):
        k = len(a)
        for j in range(n):
            if sum(1 for x in a if x > j) > n - j:
                return False
        return True

    # Generate non-decreasing sequences of length k with values in 1..n
    def generate(k, start, current):
        if len(current) == k:
            yield list(current)
            return
        for i in range(start, n + 1):
            current.append(i)
            yield from generate(k, i, current)
            current.pop()

    for k in range(2, n + 1):
        count = 0
        for a in generate(k, 1, []):
            if is_valid(a, n):
                # Check if tasty: at least one equality
                if len(set(a)) < k:
                    count += 1
        total += count
    return total

for n in range(1, 8):
    print(f"n={n}: {count_tasty(n)}")"}

{"operation":"run_python","code":"def count_le(poset, n):
    # poset is a list of (a, b) meaning a < b
    # We use DP with bitmask
    from functools import lru_cache

    # Precompute predecessors for each node
    pred = [0] * n
    for a, b in poset:
        pred[b] |= (1 << a)

    @lru_cache(None)
    def dp(mask):
        if mask == 0:
            return 1
        res = 0
        for i in range(n):
            if not (mask & (1 << i)):
                # i is available to be added next
                if (pred[i] & ~mask) == 0:
                    res += dp(mask | (1 << i))
        return res

    return dp((1 << n) - 1)

