    # Generate all lines of 4 on a 6x6 board
    lines = []
    n = 6
    for r in range(n):
        for c in range(n - 3):
            line = [(r, c+i) for i in range(4)]
            lines.append(line)
    for c in range(n):
        for r in range(n - 3):
            line = [(r+i, c) for i in range(4)]
            lines.append(line)
    # Diagonals (top-left to bottom-right)
    for r in range(n):
        for c in range(n):
            if r + 3 < n and c + 3 < n:
                line = [(r+i, c+i) for i in range(4)]
                lines.append(line)
    # Anti-diagonals (top-right to bottom-left)
    for r in range(n):
        for c in range(n):
            if r + 3 < n and c - 3 >= 0:
                line = [(r+i, c-i) for i in range(4)]
                lines.append(line)

    print(f"Total lines of 4: {len(lines)}")

