{"operation":"run_python","code":"def solve(n):
    from collections import deque

    start = tuple(range(1, n+1))
    visited = {start}
    queue = deque([start])

    best = start

    while queue:
        curr = queue.popleft()
        # Update best
        if int(''.join(map(str, curr))) < int(''.join(map(str, best))):
            best = curr

        for i in range(n-1):
            a, b = curr[i], curr[i+1]
            if a != 0 and b != 0:
                new_curr = list(curr)
                new_curr[i] = b - 1
                new_curr[i+1] = a - 1
                new_curr = tuple(new_curr)

                if new_curr not in visited:
                    visited.add(new_curr)
                    queue.append(new_curr)
    return best

for n in range(1, 8):
    res = solve(n)
    print(f"n={n}: {''.join(map(str, res))}")"}

