    total_cells = N * N
    # Precompute row and col indices for each cell
    cell_to_rc = {}
    rc_to_cell = {}
    for r in range(N):
        for c in range(N):
            idx = r * N + c
            cell_to_rc[idx] = (r, c)
            rc_to_cell[(r,c)] = idx

    # Precompute row and col masks for each cell to quickly count set bits
    # Actually, we can just count bits on the fly or precompute.
    # Let's precompute row_mask and col_mask for each cell index.
    row_masks = [0] * total_cells
    col_masks = [0] * total_cells
    for r in range(N):
        for c in range(N):
            idx = r * N + c
            mask = 0
            for k in range(N):
                mask |= (1 << (r * N + k))
            row_masks[idx] = mask

            mask = 0
            for k in range(N):
                mask |= (1 << (k * N + c))
            col_masks[idx] = mask

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def minimax(mask, turn):
        if mask == (1 << total_cells) - 1:
            return 0

        best_val = -float('inf') if turn == 0 else float('inf')

        for c in range(total_cells):
            if not (mask & (1 << c)):
                # Points = number of set bits in row_masks[c] & mask + col_masks[c] & mask
                points = bin(row_masks[c] & mask).count('1') + bin(col_masks[c] & mask).count('1')

                new_mask = mask | (1 << c)
                val = minimax(new_mask, 1 - turn)

                if turn == 0: # Alice maximizes
                    val += points
                    if val > best_val:
                        best_val = val
                else: # Bob minimizes
                    val -= points
                    if val < best_val:
                        best_val = val

        return best_val

    return minimax(0, 0)

