{"operation":"run_python","code":"import random

def simulate(n_trials=100000):
    wins = 0
    for _ in range(n_trials):
        # Bag: 5 pairs, colors 0-4. Each has 2 socks.
        bag = [0]*10
        for i in range(5):
            bag[2*i] = i
            bag[2*i+1] = i

        hand = []
        while True:
            # Draw up to 4 socks or until bag empty
            draw_count = min(4 - len(hand), len(bag))
            if draw_count == 0:
                break

            indices = random.sample(range(len(bag)), draw_count)
            drawn_socks = [bag[i] for i in indices]
            hand.extend(drawn_socks)

            # Remove drawn socks from bag
            # Since we use indices, we need to remove carefully. 
            # Easier: just pop by index sorted descending
            for idx in sorted(indices, reverse=True):
                bag.pop(idx)

            # Check for pairs and discard
            while True:
                counts = {}
                for s in hand:
                    counts[s] = counts.get(s, 0) + 1
                has_pair = False
                new_hand = []
                for s, c in counts.items():
                    if c >= 2:
                        has_pair = True
                        # discard pairs
                    else:
                        new_hand.append(s)
                if not has_pair:
                    break
                hand = new_hand

            if len(hand) == 4:
                if len(set(hand)) == 4:
                    wins += 1
                break
            if len(bag) == 0:
                break

    return wins / n_trials

print(simulate(50000))"}
